 assert(!await page.evaluate(()=>window.calls.some(c=>['vault_prepare','vault_download','vault_install','vault_cancel','vault_resume_forget'].includes(c.name))));
 checks.push('StrictMode download modal has an accessible name, safe initial focus, forward/backward Tab loop, outside-focus guard and idle Escape with focus return; no transfer starts');
